부록 2. 패킷구조정의
Center2Terminal DEFINITIONS AUTOMATIC TAGS::= BEGIN
DatexDataPacket ::= SEQUENCE {
datex-Version-nbrINTEGER,
datex-Authenticationinfo-txtOCTET STRING(SIZE(1)),
datex-Packet-nbrINTEGER,
optionsHeaderOptions,
datex-DataPDUs,
datex-Crc-nbrOCTET STRING(SIZE(2))
}
HeaderOptions ::= SEQUENCE {
datex-SenderIDOCTET STRINGOPTIONAL,
datex-ReceiverIDOCTET STRINGOPTIONAL,
datex-DataPacket-timeGeneralizedTimeOPTIONAL
}
PDUs ::= CHOICE{
subscriptionSubscription,
publicationPublication,
acceptAccept,
rejectReject
}
Subscription ::= SEQUENCE {
datexSubscription-Area-scopeENUMERATED {
local-Area,
national-Area
},
datexSubscription-Location-referenceUTF8StringOPTIONAL,
datexSubscription-Road-classBIT STRING {
expressway(0),
general-national-road(1),
urbun-road(2),
rural-road(3),
others(4)
},
datexSubscription-UserinfoSEQUENCE{
usernameUTF8String,
passwordUTF8String,
identificationIDIA5StringOPTIONAL
}OPTIONAL,
datexSubscription-PduSEQUENCE OF EndApplicationMessage
}(WITH COMPONENTS {..., datexSubscription-Area-scope(local-Area), datexSubscription-Location-reference PRESENT}
| WITH COMPONENTS {..., datexSubscription-Area-scope(national-Area), datexSubscription-Location-reference ABSENT})
Publication ::=SEQUENCE {
datexPublication-Response-existenceBOOLEAN,
datexPublication-Publication-PduSEQUENCE OF EndApplicationMessage
}
CENTER2TERMINAL-MESSAGE ::= CLASS {
&idOBJECT IDENTIFIER,
&MessageBody
}
EndApplicationMessage ::= SEQUENCE {
endApplication-Message-idCENTER2TERMINAL-MESSAGE.&id,
endApplication-Message-msgCENTER2TERMINAL-MESSAGE.&MessageBody
}
Accept ::= SEQUENCE {
datexAccept-Packet-nbrINTEGER,
datexAccept-TypeENUMERATED{
subscription,
publication
}
}
Reject ::= SEQUENCE{
datexReject-Packet-nbrINTEGER,
datexReject-TypeENUMERATED{
subscription,
publication
},
datexReject-CodeCHOICE{
subscriptionENUMERATED{
invalidUserID,
invalidPassword,
invalididentificationID,
invalidVersionNo,
invalidformat,
memoryoverflow,
invalidData,
crc-Error,
others
},
publicationENUMERATED{
invalidformat,
memoryoverflow,
invalidData,
crc-Error,
others
},
other-packetENUMERATED{
invalidformat,
invalidData,
crc-Error,
others
}
},
datexReject-ReasonUTF8StringOPTIONAL
}
END
